// wire a button to an export with visible progress, success and failure states
function exportButton(btn, run) { const label = btn.textContent; btn.onclick = async () => { if (btn.disabled) return; btn.disabled = true; btn.textContent = 'Preparing image…'; btn.setAttribute('aria-live', 'polite');
  try { const r = await run(); btn.textContent = r && r.how === 'viewer' ? 'Opened: press and hold the image to save it' : `Saved${r && r.width ? ` (${r.width} × ${r.height})` : ''}`; } catch (e) { console.error(e); btn.textContent = 'Could not save. Tap to try again'; }
  btn.disabled = false; setTimeout(() => { if (!btn.disabled) btn.textContent = label; }, 6000); }; }
addEventListener('click', (e) => { const a = e.target.closest && e.target.closest('a[data-lb]'); if (a) { e.preventDefault(); openLightbox(a.getAttribute('href'), a.dataset.lb); } });

// One weekly award from weekly.json awards[w].list: the winner is a player or a position group, with jersey tokens for who it was.
const awardItem = (a, mgrName) => `<div class="${a.key} awp"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="${AWICON[a.key] || ''}"/></svg><span>${a.label}</span><b>${esc(a.big)}</b><em>${a.points.toFixed(2)} pts · ${esc(mgrName(a.roster_id))}</em><p>${esc(a.text)}</p><footer class="awt">${a.players.slice(0, 4).map((p) => `<i data-pid="${esc(p.player_id || '')}" ${p.rank_through ? `data-pweek="${p.rank_through}"` : ''} tabindex="0" role="button" aria-label="Open ${esc(p.name)} player details">${nflBadge(p.nfl_team)}${esc(p.name)}${p.rank ? ` <small title="Season rank at the position by total points${p.rank_through ? ', as it stood after Week ' + p.rank_through : ''}">${esc(p.rank)}</small>` : ''} <u>${p.points.toFixed(1)}</u></i>`).join('')}</footer></div>`;

// Toilet Bowl punishment for a season, from src/config/punishments.json via canonical.json. Shown wherever the Toilet Bowl is mentioned.
const punishOf = (c, season) => { const p = (c.punishments || {})[season]; return p ? p.punishment + (p.outcome ? ' (' + p.outcome + ')' : '') : ''; };
const punishTag = (c, season) => { const t = punishOf(c, season); return t ? `<span class="pun">Punishment: ${esc(t)}</span>` : ''; };
// One franchise's draft capital as a board: seasons down, rounds across. Each crest is the pick's original owner; dashed crests are this franchise's own picks held by someone else.
function pickBoard(c, id) { const T = (x) => c.byRoster[x], th = (x) => c.themes[T(x).theme], f = T(id), seasons = [...new Set(c.franchises.flatMap((g) => g.future_picks.map((p) => +p.season)))].sort(), rounds = [...new Set(c.franchises.flatMap((g) => g.future_picks.map((p) => p.round)))].sort(), holder = {};
  for (const g of c.franchises) for (const p of g.future_picks) holder[`${p.season}-${p.round}-${p.original_roster}`] = g.roster_id;
  const h = f.future_picks, got = h.filter((p) => p.original_roster !== id).length, gone = seasons.length * rounds.length - h.filter((p) => p.original_roster === id).length;
  return `<div class="dark pkwrap"><div class="pk-card on" style="--c:${th(id).hi}"><div class="pk-h">${emblem(th(id))}<span><b>${esc(f.manager)}</b><small>${esc(f.team_name)}</small></span><span class="pk-n"><b>${h.length}</b>picks</span></div>
    <div class="pk-s"><span><b>${h.filter((p) => p.round === 1).length}</b> firsts</span><span><b>${got}</b> from others</span><span><b>${gone}</b> of their own gone</span></div>
    <div class="pk-g" style="grid-template-columns:44px repeat(${rounds.length},minmax(0,1fr))"><span></span>${rounds.map((r) => `<span class="pk-rh">R${r}</span>`).join('')}
    ${seasons.map((se) => `<span class="pk-y">${se}</span>${rounds.map((r) => { const held = h.filter((p) => +p.season === se && p.round === r).sort((a, b) => (b.original_roster === id) - (a.original_roster === id)), away = holder[`${se}-${r}-${id}`] !== id ? holder[`${se}-${r}-${id}`] : null;
      return `<span class="pk-c">${held.map((p) => `<a class="pc ${p.original_roster === id ? 'own' : 'got'}" href="${p.original_roster === id ? 'rivalry.html?layer=picks&a=' + f.slug : 'rivalry.html?a=' + f.slug + '&b=' + T(p.original_roster).slug}" style="--o:${th(p.original_roster).hi}" title="${se} round ${r}, ${p.original_roster === id ? 'own pick' : 'originally ' + esc(T(p.original_roster).manager) + "'s"}" aria-label="${se} round ${r}, ${p.original_roster === id ? 'own pick' : 'originally ' + esc(T(p.original_roster).manager) + "'s"}">${emblem(th(p.original_roster))}</a>`).join('')}${away ? `<a class="pc gone" href="rivalry.html?a=${f.slug}&b=${T(away).slug}" title="${se} round ${r}: own pick, now held by ${esc(T(away).manager)}" aria-label="${se} round ${r}: own pick, now held by ${esc(T(away).manager)}">${emblem(th(away))}</a>` : ''}</span>`; }).join('')}`).join('')}</div>
    <div class="pk-leg" style="padding:12px 0 0"><span class="lgc"><i class="pc own"></i>own pick</span><span class="lgc"><i class="pc got"></i>acquired: crest shows whose it was</span><span class="lgc"><i class="pc gone"></i>own pick gone: crest shows who holds it</span></div></div></div>`; }

// Which second-edition films exist this week (written by the weekly film workflow). If the list is missing, pages fall back to the first editions.
const loadEditions = (base = '') => fetch(base + 'cinematics/editions.json', { cache: 'no-cache' }).then((r) => (r.ok ? r.json() : null)).catch(() => null).then((e) => e || { franchise_second_edition: [], documentary: null });

// =====================================================================================================================
// Player inspector and search. One panel for every player, opened from any name, jersey or rank on the site
// (anything carrying data-pid), from search, or from a link ending #player=<id>. It always shows CURRENT information and says so;
// when it was opened from a past week (data-pweek), it also shows the rank as it stood after that week.
// =====================================================================================================================
let _PL = null; const loadPlayers = () => (_PL ||= Promise.all([fetch((document.querySelector('script[src$="app.js"]').getAttribute('src').replace('assets/app.js', '')) + 'data/player_log.json', { cache: 'no-cache' }).then((r) => r.json()), loadLeague(), fetch((document.querySelector('script[src$="app.js"]').getAttribute('src').replace('assets/app.js', '')) + 'data/weekly.json', { cache: 'no-cache' }).then((r) => r.json()).catch(() => null)]).catch((e) => { _PL = null; throw e; }));
const _base = () => document.querySelector('script[src$="app.js"]').getAttribute('src').replace('assets/app.js', '');
let _piOpener = null, _piPushed = false;
function closePlayer(fromPop) { const d = document.getElementById('pi'); if (!d) return; d.remove(); document.documentElement.style.overflow = ''; if (_piPushed && !fromPop) { _piPushed = false; history.back(); } _piPushed = false; if (_piOpener && document.contains(_piOpener)) _piOpener.focus({ preventScroll: true }); _piOpener = null; }
