  const d = document.createElement('dialog'); d.id = 'pi'; d.className = 'pi'; d.setAttribute('aria-label', 'Player details'); d.innerHTML = '<div class="pi-in"><p class="pi-load" role="status">Loading player…</p></div>'; document.body.appendChild(d); document.documentElement.style.overflow = 'hidden';
  d.addEventListener('cancel', (e) => { e.preventDefault(); closePlayer(); }); d.onclick = (e) => { if (e.target === d) closePlayer(); }; if (d.showModal) d.showModal(); else d.setAttribute('open', '');
  if (push && !_piPushed) { history.pushState({ pi: pid }, '', location.pathname + location.search + '#player=' + pid); _piPushed = true; } else if (_piPushed) history.replaceState({ pi: pid }, '', location.pathname + location.search + '#player=' + pid);
  let PL, c, WK; try { [PL, c, WK] = await loadPlayers(); } catch (e) { d.querySelector('.pi-in').innerHTML = `<div class="pi-top"><b>Player details are unavailable</b><button class="b2 on" id="pix">Close ✕</button></div><p class="note">The player file could not be loaded. Nothing is shown rather than guessing. <button class="b2" id="pir">Try again</button></p>`; d.querySelector('#pix').onclick = () => closePlayer(); d.querySelector('#pir').onclick = () => openPlayer(pid, { week, push: false }); return; }
  const p = PL.players[pid], B = PL.basis, tw = PL.through_week, base = _base(), f2 = (x) => x.toFixed(2);
  if (!p) { d.querySelector('.pi-in').innerHTML = `<div class="pi-top"><b>No details for this player</b><button class="b2 on" id="pix">Close ✕</button></div><p class="note">This player is not in the league's player file (he has not been on a league roster this season).</p>`; d.querySelector('#pix').onclick = () => closePlayer(); return; }
  const fr = p.own && c.byRoster[p.own.roster_id], team = (typeof NFL_NAMES !== 'undefined' && NFL_NAMES[p.tm]) || p.tm || 'Free agent';
  let tw_ = null; if (WK && WK.preview) for (const g of WK.preview.games) for (const [l, rid] of [[g.lineup_a, g.a], [g.lineup_b, g.b]]) { const x = (l || []).find((q) => String(q.player_id) === String(pid)); if (x) tw_ = { x, g, rid, live: !!g.live }; }
  const games = PL.weeks.map((w, i) => ({ w, v: p.w[i] })), played = games.filter((x) => x.v != null), mx = Math.max(10, ...played.map((x) => x.v)), rkList = p.rk ? Object.entries(p.rk) : [];
  let hist = ''; if (week && +week < tw) { try { const RK = await fetch(base + 'data/ranks.json').then((r) => r.json()); const s = RK.weeks[week] && RK.weeks[week][pid]; if (s) hist = `<div class="pi-hist"><b>You opened this from Week ${week}.</b> After Week ${week} he was <b>${esc(s[0])}</b> with ${f2(s[1])} points. Everything else on this panel is current, through Week ${tw}.</div>`; } catch (e) {} }
