addEventListener('click', (e) => { const t = e.target.closest && e.target.closest('[data-pid]'); if (!t || !t.dataset.pid || e.target.closest('a[href],#pi')) return; e.preventDefault(); openPlayer(t.dataset.pid, { week: t.dataset.pweek || null }); });
